// All BC customers -> HubSpot company payloads, in batches of 100.
// Skips blocked customers and customers without a name. maxCustomers > 0 limits the run (for testing).
const cfg = $('Workflow Config').first().json;
const asObj = (v) => (typeof v === 'string' ? JSON.parse(v) : v);
const map = asObj(cfg.companyFieldMap);       // BC Customer_Card field -> HubSpot company property
const countries = asObj(cfg.countryMap);      // 'australia' -> 'AU'
const title = (s) => s.replace(/\b\w/g, (c) => c.toUpperCase());
const countryName = Object.fromEntries(Object.entries(countries).map(([n, c]) => [c, title(n)]));
const norm = (v) => (v === null || v === undefined ? '' : String(v).trim());

let customers = [];
for (const page of $('Read BC Customers').all()) customers = customers.concat(page.json.value || []);
customers = customers.filter((c) => !norm(c.Blocked) && norm(c.Name));   // skip blocked + nameless
const max = Number(cfg.maxCustomers) || 0;
if (max > 0) customers = customers.slice(0, max);

const rows = customers.map((c) => {
  const properties = { [cfg.companyMatchProperty]: norm(c.No) };
  for (const [bcField, hsProp] of Object.entries(map)) {
    let v = norm(c[bcField]);
    if (!v) continue;                                            // blank in BC: not sent
    if (bcField === 'Country_Region_Code') v = countryName[v.toUpperCase()] || v;
    properties[hsProp] = v;
  }
  return { number: norm(c.No), properties };
});

const out = [];
for (let i = 0; i < rows.length; i += 100) {
  const customersBatch = rows.slice(i, i + 100);
  out.push({ json: { numbers: customersBatch.map((r) => r.number), customers: customersBatch } });
}
return out;

// For each batch: the HubSpot companies that already exist (matched on business_central_id) are
// left alone; the rest become the create payload. Items stay in the same order as the batches.
const cfg = $('Workflow Config').first().json;
const batches = $('Prepare Customer Batches').all();
return $input.all().map((item, i) => {
  const batch = batches[i].json;
  const existing = {};
  for (const r of item.json.results || []) existing[String(r.properties[cfg.companyMatchProperty]).trim()] = r.id;
  const inputs = batch.customers
    .filter((c) => !existing[c.number])
    .map((c) => ({ properties: c.properties }));
  return { json: { inputs, existing } };
});

// 1) Builds the full BC customer number -> HubSpot company id map (existing + just created).
// 2) Joins every BC Person contact to its customer (via the customer's company contact) and
//    returns contact batches of 100. Contacts of blocked / out-of-scope customers are skipped.
const cfg = $('Workflow Config').first().json;
const asObj = (v) => (typeof v === 'string' ? JSON.parse(v) : v);
const map = asObj(cfg.contactFieldMap);       // BC contact field -> HubSpot contact property
const norm = (v) => (v === null || v === undefined ? '' : String(v).trim());

const companyId = {};                          // BC customer number -> HubSpot company id
for (const item of $('Build Company Creates').all()) Object.assign(companyId, item.json.existing);   // already in HubSpot
for (const item of $input.all()) {                                                                    // just created
  if (item.json.errors && item.json.errors.length) {
    throw new Error(`HubSpot rejected some company creates: ${JSON.stringify(item.json.errors).slice(0, 500)}`);
  }
  for (const r of item.json.results || []) companyId[norm(r.properties[cfg.companyMatchProperty])] = r.id;
}
const scope = $('Prepare Customer Batches').all().flatMap((b) => b.json.numbers);
const missing = scope.filter((n) => !companyId[n]);
if (missing.length) throw new Error(`${missing.length} customers have no HubSpot company after the create step, e.g. ${missing.slice(0, 5).join(', ')}`);

// customer number -> its BC company contact number
const customerByCompanyContact = {};
for (const page of $('Read BC Company Contacts').all()) {
  for (const c of page.json.value || []) {
    const company = (c.contactsInformation || []).find((x) => x.contactType === 'Company');
    if (company && companyId[norm(c.number)]) customerByCompanyContact[norm(company.contactNumber)] = norm(c.number);
  }
}

// Segment / Sub_Segment live on the BC contact card page, keyed by contact number.
const pageFields = {};
for (const page of $('Read BC Contact Segments').all()) {
  for (const c of page.json.value || []) pageFields[norm(c.No)] = c;
}

const rows = [];
for (const page of $('Read BC Person Contacts').all()) {
  for (const person of page.json.value || []) {
    const p = { ...person, ...(pageFields[norm(person.number)] || {}) };
    const customer = customerByCompanyContact[norm(p.companyNumber)];
    if (!customer) continue;                                     // not linked to an in-scope customer
    const properties = { [cfg.contactMatchProperty]: norm(p.number) };
    for (const [bcField, hsProp] of Object.entries(map)) {
      const v = norm(p[bcField]);
      if (v) properties[hsProp] = v;
    }
    // Generic contacts (e.g. "ACCOUNTS") have no first name / surname in BC: use the display name instead.
    if (!properties[map.firstName] && !properties[map.surname] && norm(p.displayName)) properties[map.firstName] = norm(p.displayName);
    rows.push({ number: norm(p.number), companyId: companyId[customer], properties });
  }
}

const out = [];
for (let i = 0; i < rows.length; i += 100) {
  const contacts = rows.slice(i, i + 100);
  out.push({ json: { numbers: contacts.map((r) => r.number), contacts } });
}
return out;

// For each batch: HubSpot contacts that already exist (matched on business_central_record_id) are
// left alone; the rest become the create payload. `pairs` keeps contact -> company for the association step.
const cfg = $('Workflow Config').first().json;
const batches = $('Build Company Map And Contact Batches').all();
return $input.all().map((item, i) => {
  const batch = batches[i].json;
  const existing = {};
  for (const r of item.json.results || []) existing[String(r.properties[cfg.contactMatchProperty]).trim()] = r.id;
  const inputs = batch.contacts.filter((c) => !existing[c.number]).map((c) => ({ properties: c.properties }));
  const pairs = batch.contacts.map((c) => ({ number: c.number, companyId: c.companyId }));
  return { json: { inputs, existing, pairs } };
});

// Builds the contact -> company associations (default association, so the company becomes the
// contact's primary company). Runs for every contact, new or existing: it is idempotent.
const cfg = $('Workflow Config').first().json;
const norm = (v) => (v === null || v === undefined ? '' : String(v).trim());
const contactId = {};
for (const item of $('Build Contact Creates').all()) Object.assign(contactId, item.json.existing);   // already in HubSpot
for (const item of $input.all()) {                                                                    // just created
  if (item.json.errors && item.json.errors.length) {
    throw new Error(`HubSpot rejected some contact creates: ${JSON.stringify(item.json.errors).slice(0, 500)}`);
  }
  for (const r of item.json.results || []) contactId[norm(r.properties[cfg.contactMatchProperty])] = r.id;
}
const pairs = $('Build Contact Creates').all().flatMap((i) => i.json.pairs);
const missing = pairs.filter((p) => !contactId[p.number]);
if (missing.length) throw new Error(`${missing.length} contacts have no HubSpot id after the create step, e.g. ${missing.slice(0, 5).map((p) => p.number).join(', ')}`);

const inputs = pairs.map((p) => ({ from: { id: contactId[p.number] }, to: { id: p.companyId } }));
const out = [];
for (let i = 0; i < inputs.length; i += 100) out.push({ json: { inputs: inputs.slice(i, i + 100) } });
return out;
